import React, { useState } from 'react';
import './stylee.scss';

const Jobs = ({ onPageChange, companyFilter }) => {
  const [language, setLanguage] = useState('vi');

  const translations = {
    vi: {
      company: 'Công ty',
      jobs: 'Việc làm',
      community: 'Cộng đồng',
      contact: 'Liên hệ',
      signIn: 'Đăng nhập',
      signUp: 'Đăng ký',
      jobsAt: 'Việc làm tại',
      seeMore: 'Xem thêm',
      back: 'Quay lại'
    },
    en: {
      company: 'Company',
      jobs: 'Jobs',
      community: 'Community',
      contact: 'Contact',
      signIn: 'Log In',
      signUp: 'Sign Up',
      jobsAt: 'Jobs at',
      seeMore: 'See more',
      back: 'Back'
    }
  };

  const t = translations[language];

  const handleLogin = () => {
    window.location.href = 'http://localhost:3002?mode=login';
  };

  const handleSignup = () => {
    window.location.href = 'http://localhost:3002?mode=signup';
  };

  const handleSeeMore = (e, jobData) => {
    e.preventDefault();
    e.stopPropagation();
    onPageChange('job');
  };

  const allJobs = [
    { logo: "Samsung.png", title: language === 'vi' ? "Kỹ sư Phần mềm" : "Software Engineer", company: language === 'vi' ? "Samsung Việt Nam" : "Samsung Vietnam", companyKey: "samsung" },
    { logo: "Samsung.png", title: language === 'vi' ? "Kỹ sư QA" : "QA Engineer", company: language === 'vi' ? "Samsung Việt Nam" : "Samsung Vietnam", companyKey: "samsung" },
    { logo: "Samsung.png", title: language === 'vi' ? "Nhà phát triển Android" : "Android Developer", company: language === 'vi' ? "Samsung Việt Nam" : "Samsung Vietnam", companyKey: "samsung" },
    { logo: "LG.png", title: "Electronics Development", company: language === 'vi' ? "Công ty LG" : "LG Electronics", companyKey: "lg" },
    { logo: "Google.png", title: "Software Engineer", company: language === 'vi' ? "Công ty Google" : "Google Inc", companyKey: "google" },
    { logo: "Microsoft.png", title: "Cloud Developer", company: language === 'vi' ? "Công ty Microsoft" : "Microsoft Corp", companyKey: "microsoft" }
  ];

  const filteredJobs = companyFilter ? allJobs.filter(job => job.companyKey === companyFilter) : allJobs;
  const companyName = companyFilter === 'samsung' ? (language === 'vi' ? 'Samsung Việt Nam' : 'Samsung Vietnam') : '';

  return (
    <div>
      <nav className="navbar navbar-expand-lg bg-white shadow-sm">
        <div className="container">
          <button 
            className="btn btn-secondary btn-sm me-3"
            onClick={() => onPageChange('companyDetail')}
          >
            ←
          </button>
          <span className="navbar-brand fw-bold" style={{fontSize: '24px'}}>
            <span style={{color: '#007bff'}}>JobConnect</span><span style={{color: '#28a745'}}>4Students</span>
          </span>
          <ul className="navbar-nav ms-auto">
            <li className="nav-item">
              <span className="nav-link" style={{cursor: 'pointer'}} onClick={() => onPageChange('company')}>
                {t.company}
              </span>
            </li>
            <li className="nav-item">
              <span className="nav-link active">{t.jobs}</span>
            </li>
            <li className="nav-item">
              <span className="nav-link" style={{cursor: 'pointer'}} onClick={() => onPageChange('community')}>
                {t.community}
              </span>
            </li>
            <li className="nav-item">
              <span className="nav-link" style={{cursor: 'pointer'}} onClick={() => onPageChange('contact')}>
                {t.contact}
              </span>
            </li>
            <li className="nav-item">
              <button className="btn btn-primary me-2" onClick={handleLogin}>
                {t.signIn}
              </button>
            </li>
            <li className="nav-item">
              <button className="btn btn-primary" onClick={handleSignup}>
                {t.signUp}
              </button>
            </li>
          </ul>
          <button
            className="btn btn-outline-secondary ms-3"
            onClick={() => setLanguage(language === 'vi' ? 'en' : 'vi')}
            style={{ padding: "6px 12px" }}
          >
            <img
              src={language === 'vi' ? 'vietnam-flag.svg' : 'uk-flag.svg'}
              alt={language === 'vi' ? 'VI' : 'EN'}
              style={{ width: "20px", height: "14px" }}
            />
          </button>
        </div>
      </nav>

      <div className="container mt-4">
        {companyFilter && (
          <div className="text-center mb-4">
            <h2 style={{color: '#007bff'}}>{t.jobsAt} {companyName}</h2>
          </div>
        )}

        <div className="row">
          {filteredJobs.map((job, index) => (
            <div className="col-md-4 mb-3" key={index}>
              <div className="job-card d-flex align-items-center">
                <img 
                  src={job.logo} 
                  alt="logo" 
                  onError={(e) => {e.target.src = 'https://via.placeholder.com/50x50?text=Logo'}}
                />
                <div className="job-info">
                  <h6>{job.title}</h6>
                  <p>{job.company}</p>
                  <button 
                    type="button"
                    className="btn btn-sm btn-outline-primary"
                    onClick={(e) => handleSeeMore(e, job)}
                  >
                    {t.seeMore}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {filteredJobs.length === 0 && (
          <div className="text-center mt-5">
            <p style={{color: '#666', fontSize: '18px'}}>
              {language === 'vi' ? 'Không có việc làm nào được tìm thấy.' : 'No jobs found.'}
            </p>
          </div>
        )}
      </div>

      <footer style={{marginTop: '50px'}}>
        <div className="container text-center">
          <h5 className="fw-bold text-primary">
            JobConnect <span className="text-success">4Students</span>
          </h5>
          <p>497 Hoa Hao Street, Ward 7, District 10, Ho Chi Minh City</p>
          <p>Hotline : 0943009243</p>
          <div className="mt-2">
            <a href="#">Facebook</a> · <a href="#">Instagram</a> ·
            <a href="#">YouTube</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default Jobs;
